mermaid_source:
graph TD
    A["到达某层"] --> B{"车内有人选了这层吗"}
    B -->|是| S["停"]
    B -->|否| C{"当前方向的外呼在这层吗"}
    C -->|是| S
    C -->|否| D{"前方已无需求且需要反向吗"}
    D -->|是| E{"这层正好有反向外呼吗"}
    E -->|是| S
    E -->|否| F["不停，改方向"]
    D -->|否| G["不停，继续当前方向"]

    style S fill:#c8e6c9,stroke:#333,color:#000
    style F fill:#fff9c4,stroke:#333,color:#000
    style G fill:#bbdefb,stroke:#333,color:#000
